        background: var(--color-primary);
        color: var(--color-primary-text);
        border: none;
        border-radius: var(--radius-btn);
        font-size: 1rem;
        font-weight: 600;
        font-family: var(--font-sans);
        cursor: pointer;
        transition: background-color var(--transition), box-shadow var(--transition);
