      #form-status.success {
        display: block;
        background: #dcfce7;
        color: #15803d;
        border: 1px solid #86efac;
      }

      #form-status.error {
        display: block;
        background: #fef2f2;
        color: var(--color-error);
        border: 1px solid #fca5a5;
