    <a class="skip-link" href="#main-content">Skip to main content</a>

    <header>
      <h1>Contact Support</h1>
      <p>Fill out the form below and our team will get back to you as soon as possible.</p>
    </header>

    <main id="main-content">
      <div class="card">
        <p class="required-legend">
          <span class="req-star" aria-hidden="true">*</span>
          Required fields
        </p>

        <form id="contact-form" novalidate aria-label="Contact support form">

          <!-- Full Name -->
          <div class="form-field">
            <label for="full-name">
              Full name
              <span class="req-star" aria-hidden="true">*</span>
            </label>
            <input
              id="full-name"
              name="full-name"
              type="text"
              required
              autocomplete="name"
              aria-required="true"
              aria-describedby="full-name-error"
              placeholder="Jane Smith"
            />
            <span id="full-name-error" class="error-text" role="alert" aria-live="polite">
              <svg aria-hidden="true" width="14" height="14" viewBox="0 0 20 20" fill="currentColor" focusable="false">
                <path fill-rule="evenodd" d="M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Zm-8-5a1 1 0 0 1 1 1v4a1 1 0 1 1-2 0V6a1 1 0 0 1 1-1Zm0 8a1 1 0 1 0 0 2 1 1 0 0 0 0-2Z" clip-rule="evenodd"/>
              </svg>
              <span>Error: Full name is required.</span>
            </span>
          </div>

          <!-- Email Address -->
          <div class="form-field">
            <label for="email">
              Email address
              <span class="req-star" aria-hidden="true">*</span>
            </label>
            <input
              id="email"
              name="email"
              type="email"
              required
              autocomplete="email"
              aria-required="true"
              aria-describedby="email-error"
              placeholder="jane@example.com"
            />
            <span id="email-error" class="error-text" role="alert" aria-live="polite">
              <svg aria-hidden="true" width="14" height="14" viewBox="0 0 20 20" fill="currentColor" focusable="false">
                <path fill-rule="evenodd" d="M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Zm-8-5a1 1 0 0 1 1 1v4a1 1 0 1 1-2 0V6a1 1 0 0 1 1-1Zm0 8a1 1 0 1 0 0 2 1 1 0 0 0 0-2Z" clip-rule="evenodd"/>
              </svg>
              <span id="email-error-msg">Error: Email address is required.</span>
            </span>
          </div>

          <!-- Phone Number (optional) -->
          <div class="form-field">
            <label for="phone">
              Phone number
              <span class="optional-tag">(optional)</span>
            </label>
            <input
              id="phone"
              name="phone"
              type="tel"
              autocomplete="tel"
              aria-describedby="phone-help phone-error"
              placeholder="+1 (555) 000-0000"
            />
            <span id="phone-help" class="help-text">
              Enter your number in international format, e.g. +1 (555) 000-0000.
            </span>
            <span id="phone-error" class="error-text" role="alert" aria-live="polite">
              <svg aria-hidden="true" width="14" height="14" viewBox="0 0 20 20" fill="currentColor" focusable="false">
                <path fill-rule="evenodd" d="M18 10A8 8 0 1 1 2 10a8 8 0 0 1 16 0Zm-8-5a1 1 0 0 1 1 1v4a1 1 0 1 1-2 0V6a1 1 0 0 1 1-1Zm0 8a1 1 0 1 0 0 2 1 1 0 0 0 0-2Z" clip-rule="evenodd"/>
              </svg>
              <span>Error: Enter a valid phone number, e.g. +1 (555) 000-0000.</span>
            </span>
          </div>

          <div class="form-actions">
            <button type="submit">Send message</button>
          </div>
        </form>

        <!-- Status message (live region for AT) -->
        <div id="form-status" role="status" aria-live="polite" aria-atomic="true"></div>
      </div>
    </main>

    <script>
      (function () {
        const form   = document.getElementById('contact-form');
        const status = document.getElementById('form-status');

        // ── Validators ────────────────────────────────────────────
        const validators = {
          'full-name': (v) => v.trim().length > 0
            ? null
            : 'Error: Full name is required.',

          'email': (v) => {
            if (!v.trim()) return 'Error: Email address is required.';
            // RFC-5322-lite pattern
            if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(v.trim()))
              return 'Error: Enter a valid email address, e.g. name@example.com.';
            return null;
          },

          'phone': (v) => {
            if (!v.trim()) return null; // optional
            // Allow digits, spaces, hyphens, parentheses, leading +
            if (!/^\+?[\d\s\-(). ]{7,20}$/.test(v.trim()))
              return 'Error: Enter a valid phone number, e.g. +1 (555) 000-0000.';
            return null;
          },
        };

        // ── Show / clear error for one field ──────────────────────
        function setFieldError(id, message) {
          const input     = document.getElementById(id);
          const errorEl   = document.getElementById(id + '-error');
          const errorText = errorEl ? errorEl.querySelector('span:last-of-type') : null;

          if (message) {
            input.setAttribute('aria-invalid', 'true');
            if (errorText) errorText.textContent = message;
            errorEl && errorEl.classList.add('visible');
          } else {
            input.removeAttribute('aria-invalid');
            errorEl && errorEl.classList.remove('visible');
          }
        }

        // ── Validate a single field and return error or null ──────
        function validateField(id) {
          const input = document.getElementById(id);
          const error = validators[id] ? validators[id](input.value) : null;
          setFieldError(id, error);
          return error;
        }

        // ── Inline validation on blur ─────────────────────────────
        ['full-name', 'email', 'phone'].forEach((id) => {
          const input = document.getElementById(id);

          input.addEventListener('blur', () => validateField(id));

          // Re-validate on input after first error to give quick feedback
          input.addEventListener('input', () => {
            if (input.getAttribute('aria-invalid') === 'true') {
              validateField(id);
            }
          });
        });

        // ── Submit ────────────────────────────────────────────────
        form.addEventListener('submit', (e) => {
          e.preventDefault();

          const fields  = ['full-name', 'email', 'phone'];
          const errors  = fields.map((id) => ({ id, error: validateField(id) }))
                                .filter((f) => f.error !== null);

          // Clear previous status
          status.className = '';
          status.textContent = '';

          if (errors.length > 0) {
            // Focus the first invalid field
            document.getElementById(errors[0].id).focus();
            return;
          }

          // Simulate submission success
          form.reset();
          fields.forEach((id) => setFieldError(id, null));

          status.className = 'success';
          status.textContent = 'Your message has been sent. We\'ll be in touch shortly.';
          status.focus();
        });
      })();
    </script>
  </body>
</html>
